with parsed as (select id, log_ts, latency_ms, payload_json, get_json_object(payload_json, '$.user.id') as user_id, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries as retry_count, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec from app_logs where to_date(log_ts) < '2024-10-01') select case when duration_sec >= 4.4 then 'PREMIUM' else 'STANDARD' end as duration_sec_tier, bit_and(latency_ms) as latency_ms_bit_and, max(log_ts) as ended_at from parsed group by duration_sec_tier order by duration_sec_tier desc nulls first
